{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_analysis",
        "description_text",
        "distribution_section"
      ]
    },
    "title_analysis": {
      "type": "Text",
      "props": {
        "text": "Fruit Preference Analysis",
        "variant": "h2"
      },
      "children": []
    },
    "description_text": {
      "type": "Text",
      "props": {
        "text": "This section outlines the distribution of fruit preferences based on the provided data, suitable for visualization as a pie chart.",
        "variant": "body"
      },
      "children": []
    },
    "distribution_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "distribution_header",
        "fruit_preference_table"
      ]
    },
    "distribution_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "align": "center",
        "gap": "sm"
      },
      "children": [
        "pie_chart_icon",
        "distribution_title"
      ]
    },
    "pie_chart_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000320_01_1_pie-chart.svg"
      },
      "children": []
    },
    "distribution_title": {
      "type": "Text",
      "props": {
        "text": "Distribution of Fruit Preferences",
        "variant": "h2"
      },
      "children": []
    },
    "fruit_preference_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "fruit",
            "label": "Fruit"
          },
          {
            "key": "percentage",
            "label": "Percentage"
          }
        ],
        "rows": [
          {
            "fruit": "Apple",
            "percentage": 40
          },
          {
            "fruit": "Banana",
            "percentage": 30
          },
          {
            "fruit": "Orange",
            "percentage": 20
          },
          {
            "fruit": "Grape",
            "percentage": 10
          }
        ],
        "domain": "generic",
        "preferredPresentation": "cards",
        "primaryColumn": "fruit",
        "highlightColumns": ["percentage"]
      },
      "children": []
    }
  }
}
